    "translation": [
      "Saya pergi ke Kyoto. Dan saya juga pergi ke Nara. Saya sarapan. Setelah itu, saya pergi ke sekolah. Saya pergi ke supermarket lalu membeli sayuran.",
      "Saya pulang ke rumah lalu mengerjakan PR. Kemarin saya sibuk sehingga lelah.",
      "Pada hari yang ada waktu, masakan sederhana juga dibuat. Setelah makan, jadwal berikutnya diperiksa. Ada rencana berikutnya yang berkaitan dengan makanan atau belanja. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Beberapa informasi diperiksa dari pagi hingga siang.",
      "Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Sebelum berbelanja, daftar belanja dibuat. Di toko, harga dan barang yang diperlukan diperiksa. Di rumah, keluarga makan bersama."
    ],
