    "translation": [
      "Saya mandi lalu tidur. Pagi hari saya bangun lalu mencuci muka. Saya sarapan. Setelah itu, saya pergi ke sekolah.",
      "Saya pergi ke Kyoto. Dan saya juga pergi ke Nara. Masakan ini pedas dan enak. Saya berjalan sampai stasiun lalu naik kereta.",
      "Setelah memastikan waktu, kegiatan utama dilakukan. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Waktu keberangkatan dan jadwal kereta diperiksa. Di stasiun, peta dan petunjuk dilihat.",
      "Lokasi yang tidak dipahami ditanyakan kepada petugas stasiun. Barang bawaan dibuat sesedikit mungkin. Di tengah perjalanan, waktu diperiksa sekali lagi. Ada rencana untuk perjalanan berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan."
    ],
