      "Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu."
