    "translation": [
      "Pada hari libur penulis melakukan hal seperti membaca buku dan memasak. Minggu lalu ia pergi ke taman bersama teman, mengambil foto dan minum kopi. Akhir-akhir ini kemampuan memasaknya membaik, tetapi ia belum membuat masakan Jepang.",
      "Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan.",
      "Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Sebelum berbelanja, daftar belanja dibuat. Di toko, harga dan barang yang diperlukan diperiksa."
    ],
