    "translation": [
      "Penulis datang ke Tokyo tiga bulan lalu. Awalnya cara naik kereta sulit, tetapi setelah naik kereta setiap hari, kehidupannya kini menjadi lebih mudah. Bahasa Jepangnya juga sedikit membaik. Ia pernah ke Asakusa, tetapi belum pernah/pergi ke Hakone.",
      "Pada hari libur penulis berjalan-jalan di sekitar kota dan berbelanja di toko kecil. Ia mulai terbiasa dengan kehidupan di Tokyo. Bulan depan seorang teman akan datang ke Tokyo, dan penulis ingin mengajaknya melihat Asakusa serta taman.",
      "Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Waktu keberangkatan dan jadwal kereta diperiksa.",
      "Di stasiun, peta dan petunjuk dilihat. Lokasi yang tidak dipahami ditanyakan kepada petugas stasiun. Barang bawaan dibuat sesedikit mungkin. Di tengah perjalanan, waktu diperiksa sekali lagi."
    ],
